 20	/**
 21	 * Loads, validates, and returns the application configuration from `config.json`.
 22	 *
 23	 * **Setup:** Copy `config.dist.json` to `config.json` and fill in the required
 24	 * fields before running the tool.
 25	 *
 26	 * @param configPath Optional absolute path to the config file. Defaults to the
 27	 *   `config.json` in the tool root. Pass a custom path in tests to avoid touching
 28	 *   the real config file.
 29	 * @throws {Error} If `config.json` does not exist (with instruction to copy from
 30	 *   `config.dist.json`).
 31	 * @throws {Error} If any required field is missing, non-string, or empty.
 32	 */
 33	export function loadConfig(configPath?: string): AppConfig {
 34	    const resolvedConfigPath = configPath ?? getConfigPath();
 35	    let raw: Record<string, unknown>;
 36	
 37	    try {
 38	        raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
 39	    } catch (err) {
 40	        if (err instanceof FileNotFoundError) {
 41	            throw new Error(
 42	                `config.json not found at "${resolvedConfigPath}". ` +
 43	                `Copy config.dist.json to config.json and fill in the required fields.`
 44	            );
 45	        }
 46	        throw err;
 47	    }
 48	
 49	    for (const field of REQUIRED_FIELDS) {
 50	        const value = raw[field];
 51	        if (typeof value !== 'string' || value.trim() === '') {
 52	            throw new Error(
 53	                `Configuration error: required field "${field}" must be a non-empty string in config.json.`
 54	            );
 55	        }
 56	    }
 57	
 58	    return {
 59	        projectsFolder: raw['projectsFolder'] as string,
 60	        storageFolder: raw['storageFolder'] as string,
 61	        cloneDepth: typeof raw['cloneDepth'] === 'number' ? raw['cloneDepth'] : DEFAULTS.cloneDepth,
 62	        serverPort: typeof raw['serverPort'] === 'number' ? raw['serverPort'] : DEFAULTS.serverPort,
 63	        gitPollingIntervalSeconds:
 64	            typeof raw['gitPollingIntervalSeconds'] === 'number'
 65	                ? raw['gitPollingIntervalSeconds']
 66	                : DEFAULTS.gitPollingIntervalSeconds,
 67	        gitCredentials: parseGitCredentials(raw['gitCredentials']),
 68	        webserverUrl: typeof raw['webserverUrl'] === 'string' && raw['webserverUrl'].trim() !== ''
 69	            ? raw['webserverUrl'].trim().replace(/\/+$/, '')
 70	            : undefined,
 71	        notesCardHeight: typeof raw['notesCardHeight'] === 'number' ? raw['notesCardHeight'] : DEFAULTS.notesCardHeight,
 72	        notesColumns: typeof raw['notesColumns'] === 'number' ? raw['notesColumns'] : DEFAULTS.notesColumns,
 73	    };
 74	}
