 77	 * Validates and returns the `gitCredentials` value from the raw config.
 78	 *
 79	 * @returns undefined when the field is absent or null.
 80	 * @throws {Error} If the value is present but is not a plain object, or if any
 81	 *   key maps to a non-string or empty-string token.
 82	 */
 83	function parseGitCredentials(value: unknown): Record<string, string> | undefined {
 84	    if (value === undefined || value === null) {
 85	        return undefined;
 86	    }
 87	
 88	    if (typeof value !== 'object' || Array.isArray(value)) {
 89	        throw new Error(
 90	            'Configuration error: "gitCredentials" must be a plain object mapping hostnames to credential strings.'
 91	        );
 92	    }
 93	
 94	    const credentials = value as Record<string, unknown>;
 95	
 96	    for (const [key, token] of Object.entries(credentials)) {
 97	        if (typeof token !== 'string') {
 98	            throw new Error(
 99	                `Configuration error: gitCredentials["${key}"] must be a string, got ${typeof token}.`
